function flagHeldOrders(orders, limits) {
  const flagged = [];
  for (const order of orders) {
    if (order.open && order.items.length > 0) {
      for (const item of order.items) {
        if (item.qty > limits.qty && item.price > limits.price) {
          for (const tag of item.tags) {
            if (tag.startsWith("hold") || tag.startsWith("review")) {
              flagged.push(order.id + ":" + item.sku + ":" + tag);
            }
          }
        }
      }
    }
  }
  return flagged;
}

module.exports = { flagHeldOrders };

