function summarizeLedger(entries, rules) {
  const summary = [];
  for (const entry of entries) {
    if (entry.posted && entry.lines.length > 0) {
      for (const line of entry.lines) {
        if (line.amount > rules.amount && line.account !== rules.skip) {
          for (const note of line.notes) {
            if (note.kind === "audit" || note.kind === "adjust") {
              summary.push(entry.id + "/" + line.account + "/" + note.kind);
            }
          }
        }
      }
    }
  }
  return summary;
}

module.exports = { summarizeLedger };

